begin;
CREATE OR REPLACE FUNCTION public.gt_ingest_priority_events_v1(p_source uuid, p_events jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare src record; e jsonb; k text; sid uuid; n int:=0; fresh_count int:=0; held int:=0; kind text; state text; pub boolean; begin select s.source_name,s.source_url,p.* into src from gt_atlanta_priority_policy_v1 p join gt_event_sources s on s.id=p.source_id where p.source_id=p_source and p.enabled and lower(s.city)='atlanta'; if not found then raise exception 'unknown_atlanta_source'; end if; if jsonb_typeof(p_events)<>'array' or jsonb_array_length(p_events)>150 then raise exception 'invalid_event_batch'; end if; perform pg_advisory_xact_lock(hashtext('gt_atl_priority_ingest')); for e in select value from jsonb_array_elements(p_events) loop if coalesce(e->>'name','')='' or coalesce(e->>'sourceUrl','') !~ '^https://' or coalesce(e->>'venue','')='' then continue; end if; k:=md5('atlanta|'||regexp_replace(lower(e->>'name'),'[^a-z0-9]+',' ','g')||'|'||(e->>'date')||'|'||coalesce(e->>'time','unknown')||'|'||regexp_replace(lower(e->>'venue'),'[^a-z0-9]+',' ','g')); kind:=case when e->>'eventType' in ('concert','comedy','festival','play','musical','sports','special_event','activation','nightlife','brunch') then e->>'eventType' else 'special_event' end; state:=case when coalesce((e->>'cancelled')::boolean,false) then case when e#>>'{raw,eventStatus}' ilike '%postponed%' then 'postponed' else 'cancelled' end when coalesce((e->>'soldOut')::boolean,false) then 'sold_out' else 'confirmed' end; pub:=coalesce((e->>'publication')::boolean,false) and state in ('confirmed','sold_out') and coalesce(e->>'name','') !~* '(season tickets|season pass|parking pass|parking only|premium season|fast lane|vip upgrade)'; sid:=null; select show_id into sid from gt_atlanta_event_evidence_v1 where occurrence_key=k; if sid is null then select id into sid from gt_shows s where s.city_key='atlanta' and s.show_date=(e->>'date')::date and regexp_replace(lower(s.event_name),'[^a-z0-9]+',' ','g')=regexp_replace(lower(e->>'name'),'[^a-z0-9]+',' ','g') and regexp_replace(lower(s.venue_name),'[^a-z0-9]+',' ','g')=regexp_replace(lower(e->>'venue'),'[^a-z0-9]+',' ','g') and coalesce(s.show_time,'unknown')=coalesce(e->>'time','unknown') order by updated_at desc limit 1; end if; if sid is not null and (pub or state in ('cancelled','postponed','sold_out')) then update gt_shows set status=state,show_time=coalesce(e->>'time',show_time),ticket_url=coalesce(e->>'ticket',ticket_url),image_url=coalesce(e->>'image',image_url),source=src.source_name,source_url=e->>'sourceUrl',event_type=kind,is_sold_out=state='sold_out',updated_at=now() where id=sid; elsif sid is null and pub then insert into gt_shows(city_key,show_date,show_time,event_name,event_type,venue_name,venue_address,ticket_url,image_url,source,source_url,status,is_sold_out,needs_image_sourcing,freshness_tier,is_curated,curation_reason) values('atlanta',(e->>'date')::date,e->>'time',e->>'name',kind,e->>'venue',e->>'address',e->>'ticket',e->>'image',src.source_name,e->>'sourceUrl',state,state='sold_out',false,'fresh',false,'Official-source candidate; final editorial gate applies') returning id into sid; fresh_count:=fresh_count+1; else held:=held+1; end if; insert into gt_sourced_events(city,event_name,event_date,event_time,end_date,end_time,venue_name,venue_address,event_type,ticket_url,image_url,source_id,source_url,source_name,is_verified,is_published,published_to_gt,dedup_hash,raw_data,updated_at) values('atlanta',e->>'name',(e->>'date')::date,e->>'time',nullif(e->>'endDate','')::date,e->>'endTime',e->>'venue',e->>'address',kind,e->>'ticket',e->>'image',p_source,e->>'sourceUrl',src.source_name,coalesce((e->>'verified')::boolean,false),pub,sid is not null,'priority:'||k,coalesce(e->'raw','{}'::jsonb)||jsonb_build_object('priority_scout_occurrence',k,'publication_reason',e->>'publicationReason','show_id',sid,'discovery_only',not pub),now()) on conflict(dedup_hash) do update set event_time=excluded.event_time,end_date=excluded.end_date,end_time=excluded.end_time,ticket_url=excluded.ticket_url,image_url=excluded.image_url,is_verified=excluded.is_verified,is_published=excluded.is_published,published_to_gt=excluded.published_to_gt,raw_data=excluded.raw_data,updated_at=now(); insert into gt_atlanta_event_evidence_v1(occurrence_key,show_id,source_id,source_url,event_date,event_time,venue_name,verified_at,eligible,reason,market_scope,event_status,facts) values(k,sid,p_source,e->>'sourceUrl',(e->>'date')::date,e->>'time',e->>'venue',now(),pub,case when coalesce(e->>'name','') ~* '(season tickets|season pass|parking pass|parking only|premium season|fast lane|vip upgrade)' then 'ticket_add_on_or_season_product_not_event' else coalesce(e->>'publicationReason','review') end,coalesce(e#>>'{raw,scope}','atlanta'),state,jsonb_build_object('name',e->>'name','locality',e->>'locality','ticket',e->>'ticket','image',e->>'image','performer',e->>'performer','priority',src.priority,'source_name',src.source_name,'parser','priority-scout-v1')) on conflict(occurrence_key) do update set show_id=coalesce(excluded.show_id,gt_atlanta_event_evidence_v1.show_id),source_id=excluded.source_id,source_url=excluded.source_url,verified_at=excluded.verified_at,eligible=excluded.eligible,reason=excluded.reason,event_status=excluded.event_status,facts=excluded.facts; n:=n+1; end loop; return jsonb_build_object('occurrences_processed',n,'new_show_candidates',fresh_count,'held_out_of_show_inventory',held,'scope','Atlanta evidence intake; not homepage certification'); end $function$;
-- Retain the new private evidence receipts and source links.
commit;
